        if (attacker != null && target != null &&
            Custodes11EnsureKatahChoice(attacker, target))
        {
            return;
        }


        Fight11TryFight(attacker, target);
    }

    private List<WeaponAttackSelection>
        GetEligibleMeleeWeapons(
            SquadController attacker,
            SquadController target)
    {
        List<WeaponAttackSelection> result =
            new List<WeaponAttackSelection>();

        foreach (ModelToken model
            in JoinedModels(attacker))
        {
            float distance =
                ModelDistanceToSquad(
                    model,
                    target
                );

            if (distance >
                EngagementRange +
                0.05f)
            {
                continue;
            }

            List<WeaponData> weapons =
                model.MeleeWeapons
                    .Where(
                        weapon =>
                            weapon != null
                    )
                    .ToList();

            if (weapons.Count == 0)
                continue;

            // Extra Attacks profiles are made in addition to the one normal
            // melee weapon the model selects.
            List<WeaponData> extraAttacks =
                weapons
                    .Where(
                        weapon =>
                            RulesEngine.HasKeyword(
                                weapon,
                                "extra_attacks"
                            )
                    )
                    .GroupBy(
                        weapon =>
                            weapon.id ??
                            weapon.displayName
                    )
                    .Select(
                        group =>
                            group.First()
                    )
                    .ToList();

            List<WeaponData> normalWeapons =
                weapons
                    .Where(
                        weapon =>
                            !RulesEngine.HasKeyword(
                                weapon,
                                "extra_attacks"
                            )
                    )
                    .GroupBy(
                        weapon =>
                            weapon.id ??
                            weapon.displayName
                    )
                    .Select(
                        group =>
                            group.First()
                    )
                    .ToList();

            WeaponData selectedNormal =
                normalWeapons
                    .OrderByDescending(
                        weapon =>
                            EstimateMeleeWeaponValue(
                                model,
                                target,
                                weapon
                            )
                    )
                    .FirstOrDefault();

            if (selectedNormal != null)
            {
                result.Add(
                    new WeaponAttackSelection(
                        model,
                        selectedNormal
                    )
                );
            }

            foreach (WeaponData weapon
                in extraAttacks)
            {
                result.Add(
                    new WeaponAttackSelection(
                        model,
                        weapon
                    )
                );
            }

            // Edge case: a data source presents only an Extra Attacks profile.
            if (selectedNormal == null &&
                extraAttacks.Count == 0)
            {
                WeaponData fallback =
                    weapons.FirstOrDefault();

                if (fallback != null)
                {
                    result.Add(
                        new WeaponAttackSelection(
                            model,
                            fallback
                        )
                    );
                }
            }
        }

        return result;
    }

    private float EstimateMeleeWeaponValue(
        ModelToken model,
        SquadController target,
        WeaponData weapon)
    {
        if (weapon == null)
            return 0f;

        SquadController attackOwner =
            model.Squad != null
            ? model.Squad
            : selectedSquad;

        int skill =
            attackOwner != null
            ? attackOwner.GetMeleeSkill(
                target,
                weapon
              )
            : Mathf.Clamp(
                weapon.skill,
                2,
                6
              );

        float hitChance =
            Mathf.Clamp01(
                (7f - skill) /
                6f
            );

        int woundNeeded =
            RulesEngine.WoundRollNeeded(
                weapon.strength,
                target.Toughness
            );

        float woundChance =
            Mathf.Clamp01(
                (7f - woundNeeded) /
                6f
            );

        int saveNeeded =
            Mathf.Clamp(
                target.GetSave(
                    attackOwner
                ) -
                weapon.ap,
                2,
                7
            );

        float failedSaveChance =
            saveNeeded >= 7
            ? 1f
            : Mathf.Clamp01(
                (saveNeeded - 1f) /
                6f
              );

        float averageAttacks =
            RulesEngine.AverageCharacteristic(
                weapon.attacksExpression,
                weapon.attacksPerModel
            );

        float averageDamage =
            RulesEngine.AverageCharacteristic(
                weapon.damageExpression,
                weapon.damage
            );

        if (RulesEngine.HasKeyword(
            weapon,
            "torrent"))
        {
            hitChance = 1f;
        }

        return
            averageAttacks *
            hitChance *
            woundChance *
            failedSaveChance *
            averageDamage;
    }

